      card("خط‌کش او: میانگین کل بازار", ["در مینی‌دوره «مدیریت بحران مالی» (آذر ۱۴۰۴) میانگین کل بازار را برای همین متغیرها می‌دهد، بر پایه فروش تا مهر ۱۴۰۴. قاعده‌اش ساده است: بهتر از میانگین بازار، خوب.", "P/E، P/S و P/B: پایین‌تر بهتر؛ مگر حاشیه سود بالا باشد که P/S بالاتر را توجیه کند.", "حاشیه سود: ۱۵٪ میانگین است و بالای ۳۰٪ را «خیلی خوب» می‌داند؛ در گیج سه‌رنگش (قرمز، خاکستری، سبز) ۳۰٪ خط‌کش است.", "تقسیم سود بالاتر، دوره وصول و گردش کالای کوتاه‌تر و مطالبات کمتر، بهتر.", "این میانگین‌ها با زمان عوض می‌شوند و آستانه امتیاز FIS هم نیستند."], { tb: tb(["میانگین کل بازار، پاییز ۱۴۰۴", "عدد"], [["P/E آینده‌نگر", "۶.۴"], ["P/S", "حدود ۱"], ["P/A", "حدود ۱.۳"], ["P/B", "حدود ۳.۶"], ["رشد فروش", "۵۰ تا ۵۷٪"], ["مطالبات به دارایی", "۳۳٪"], ["تقسیم سود (از سود قابل تقسیم)", "۵۳٪"], ["دوره گردش کالا", "۱۰۳ روز"], ["دوره وصول مطالبات", "حدود ۴ ماه"], ["حاشیه سود FIS", "۱۵٪"]]), qt: "سود تقسیمی ملاک شما قرار داده بشه", by: "ویدیوی «مینی دوره مدیریت بحران مالی، قسمت هفتم: نسبت های برتر مالی»، یوتیوب، آذر ۱۴۰۴، دقیقه ۳۰ (متن پیاده‌شده)" }),
      card("P/D: نسبتی که حالا ترجیح می‌دهد", ["در ویدیوهای اخیرش می‌گوید بازار بیشتر به P/D نگاه می‌کند تا P/E.", "P/D آینده‌نگر = ارزش بازار ÷ سود نقدی پیش‌بینی‌شده (سود خالص پیش‌بینی × نسبت تقسیم). یعنی چند سال سود نقدی لازم است تا پول خرید برگردد.", "P/D حدود ۳ را ایده‌آل می‌داند، چون پول خرید زیر سه سال برمی‌گردد؛ همان «دارایی رایگان».", "به گفته او اگر نرخ بهره از ۴۰٪ به ۲۵٪ برسد، P/D بازار ممکن است به ۸ تا ۱۰ برسد.", "در کانالش سقف را «P/D زیر ۵» می‌نویسد. P/D برابر ۵ یعنی بازده نقدی ۲۰٪ (۱ ÷ ۵)؛ در پستی دیگر هم «نرخ بازدهی سرمایه ۲۰٪ به بالا برای سال اول» را در فهرست معیارهایش آورده.", "در پست‌هایش نسبت تقسیم را میانگین سال‌های اخیر می‌گیرد (مثلاً «میانگین تقسیم سود 90 درصدی»).", "در دی ۱۴۰۴، در پستی درباره جهش بورس ونزوئلا، نوشت «رو دلار ۷۰ ۸۰ تومان پی به دی زیر ۵ هنر شماست»: هنر این است که پیش از جهش ارز، وقتی دلار ۷۰ تا ۸۰ هزار تومان بود، سهم با P/D زیر ۵ خریده باشید."], { f: "P/D آینده‌نگر = ارزش بازار ÷ (سود خالص پیش‌بینی × میانگین نسبت تقسیم)", qt: "کمااینکه در بورس به دنبال سهم های p/d زیر ۵ هستیم", by: "کانال تلگرام پیشرفت مالی، پست ۸۶۲۰، آبان ۱۴۰۰" }),
      card("اندیکاتور FIS: خرید در ۴، فروش در ۸", ["قاعده‌ای که در یکی از ویدیوها «اندیکاتور FIS» می‌نامد:", "قیمت خرید = میانگین دو قیمت: قیمتی که P/E آینده‌نگر را ۴ می‌کند و قیمتی که P/D آینده‌نگر را ۴ می‌کند.", "قیمت فروش = همین میانگین با عدد ۸.", "در نسخه کامل‌تر، P/S و P/B را هم وارد میانگین می‌کند.", "این با مثال مقاله (خرید ۳.۵ تا ۴، خروج ۷ تا ۸) جور است."], { f: "قیمت خرید = ۲ × (سود هر سهم + سود نقدی هر سهم)، هر دو آینده‌نگر", qt: "خیلی ساده بنده میگم آقا رنج خرید باشه پی به ای عدد 4 به اضافه پی به دی 4 تقسیم بره دو", by: "ویدیوی «بنیادی یا تکنیکال؟ مسئله این است!»، آپارات، فروردین ۱۴۰۵، دقیقه ۳ (متن پیاده‌شده)" }),
card("P/E خرید از نرخ بانکی: قاعده خودش", ["مقاله فقط می‌گوید محدوده P/E از «نرخ بهره بدون ریسک به‌علاوه صرف ریسک بازار» می‌آید. در ویدیوهای ۱۴۰۴ و ۱۴۰۵ خودش آن را ساده گفته است:", "P/E درآمد ثابت (۱ ÷ نرخ) را حساب کن و سهم را حدود یک واحد بالاتر بخر. مثال خودش: وقتی P/E بانکداری ۳ است، سهم با P/E ۴ خریده می‌شود؛ اگر به ۲ برسد، سهم با P/E ۳ (ویدیوی «۱۰ ریسک و ۱۰ فرصت بازار بورس»، شهریور ۱۴۰۵).", "با درآمد ثابت حدود ۴۰٪، P/E بدون ریسک ۲.۵ است و خرید حدود ۳.۵ تا ۴؛ همان مثال مقاله. منطقش: اوراق ۴۰٪ در دو سال و نیم پولش را برمی‌گرداند، پس سهم باید حدود ۳ تا ۳.۵ سال برگرداند.", "هدف فروش هم ثابت نیست: در نرخ‌های بهره رکوردی هدف را پایین‌تر می‌آورد (در یک لایو دی ۱۴۰۴ از حدود ۸.۵ به حدود ۵.۵؛ متن ماشینی آن بخش کاملاً واضح نیست).", "جهت این رابطه را در کانالش با نمودار هم نشان داده: اخزای بالاتر، P/E بازار پایین‌تر. به نوشته او میانگین P/E بازار از حدود ۲۳ در ۱۳۹۹ به حدود ۷ در تیر ۱۴۰۵ رسید، و نرخ اخزا در بهمن ۱۴۰۴ حدود ۳۹.۷٪ بود."], { f: "P/E خرید ≈ (۱ ÷ نرخ درآمد ثابت) + حدود ۱", qt: "با افزایش نرخ اخزا طی سالیان گذشته نسبت P/E TTM بازار همواره نسبت‌های پایین‌تری را تجربه کرده است", by: "کانال تلگرام پیشرفت مالی، پست ۲۱۲۱۸، آذر ۱۴۰۴" }),
      card("حکم‌های خودش: ارزنده یا گران؟", ["از شهریور ۱۴۰۲ تا اردیبهشت ۱۴۰۳ زیر بعضی تحلیل‌های کانالش یک حکم کوتاه نوشته: «ارزنده و جذاب» یا «طبق سیستم معاملاتی FIS ارزنده و جذاب نیست»، کنار P/E آینده‌نگر همان پست. ۱۴ حکم درباره ۱۳ شرکت در جدول زیر آمده است؛ «جذاب» یعنی «ارزنده و جذاب»، «نیست» یعنی «ارزنده و جذاب نیست» و «گران» یعنی نوشته گران است و توصیه به خرید نمی‌شود.", "هر دو «جذاب» زیر ۵ بودند و همه «نیست»ها از ۸.۸۵ به بالا. این برداشت ما از همین ۱۴ پست است، نه قاعده‌ای که خودش نوشته باشد.", "میان این دو چه؟ در ویدیوی آبان ۱۴۰۴ درباره P/E حدود ۶.۵ می‌گوید «الان نه گرونه نه جذابه» و اضافه می‌کند که زیر P/E پنج جذاب می‌شود.", "با مثال مقاله هم‌خوان است: خرید حدود ۳.۵ تا ۴، خروج حدود ۷ تا ۸؛ و محدوده با نرخ اخزا جابه‌جا می‌شود (کارت قبل).", "P/E بانک ملت از عددهای خود پست درمی‌آید: ارزش بازار ۱۷۹٬۰۰۰ ÷ سود خالص برآوردی ۱۴۰۲ (بدون سود تسعیر) ۳۶٬۵۴۵ میلیارد تومان ≈ ۴.۹.", "این‌ها حکم همان روز با همان قیمت‌اند؛ چند پست درباره عرضه اولیه بود. نمونه آموزشی‌اند، نه توصیه امروز."], { tb: tb(["نماد", "P/E", "حکم"], [["وبملت", "۴.۹", "جذاب"], ["شپنا", "۴.۳", "جذاب"], ["درهآور", "۸.۸۵", "نیست"], ["فن افزار", "۱۰.۸۴", "نیست"], ["خرینگ", "۱۲.۱", "گران"], ["فنر", "۱۲.۲۴", "نیست"], ["آردینه", "۱۲.۵ و ۱۷.۱۶", "نیست (۲ پست)"], ["نخریس", "۱۳.۱۵", "نیست"], ["خچرخش", "۱۳.۲۵", "نیست"], ["کمنگنز", "۱۴.۵", "گران، نیست"], ["فلامی", "۳۳.۸", "نیست"], ["کسرام", "۶۲.۹۳", "نیست"], ["غنوش", "۶۹.۰۱", "نیست"]]), qt: "بانک ملت در حال حاضر ارزنده و جذابه", by: "کانال تلگرام پیشرفت مالی، پست ۱۵۰۴۵، دی ۱۴۰۲" })
