      card("حاشیه سود FIS، حاشیه عملیاتی نیست", ["در همان پست، سود عملیاتی ۶ ماهه ۸۷۳ و فروش ۱٬۷۲۰ است؛ تقسیم ساده‌اش حدود ۵۱٪ می‌شود. ولی او حاشیه سود FIS را ۳۷.۳٪ نوشته است.", "یعنی «سود FIS» همان سود عملیاتی گزارش نیست. مقاله هم آن را سودی محافظه‌کارانه تعریف می‌کند که اقلام غیرعملیاتی و غیرتکرارشونده را کنار می‌گذارد.", "جزئیات این تعدیل‌ها در پست‌های عمومی نیامده است. اگر خودتان با «سود عملیاتی ÷ فروش» حساب کنید، عددتان از عدد او خوش‌بینانه‌تر است.", "در همان لایو می‌گوید P/E را فقط با سود تکرارشونده حساب کنید."], { qt: "شما دنبال سودی باید باشی که هر سال تکرار بشه", by: "ویدیوی «لایو تخصصی افزایش سرمایه شرکت‌ها»، یوتیوب، آذر ۱۴۰۴، دقیقه ۲۷ (متن پیاده‌شده)" }),
      card("همه ستون‌های قالب", ["در نسخه کامل (مثلاً تحلیل عرضه اولیه شیفته، خرداد ۱۴۰۵) بعد از سود برآوردی این ستون‌ها را هم می‌آورد:", "P/A (ارزش بازار ÷ کل دارایی‌ها) و P/B (ارزش بازار ÷ حقوق صاحبان سهام).", "دوره گردش کالا و دوره وصول مطالبات، به روز.", "درصد تقسیم سود دو سال اخیر، مبلغ سود نقدی و رشدش نسبت به سال قبل.", "در گزارش‌های ماهانه: فروش این ماه در برابر ماه قبل، میانگین ماه‌های قبل و ماه مشابه پارسال؛ و نسبت مطالبات به دارایی‌ها.", "بیشتر این ستون‌ها همان ۱۱ متغیر مقاله‌اند.", "و پیش از همه، گزارش حسابرس: با اظهارنظر مردود یا بندهای زیاد، عددهای قالب قابل اتکا نیست."], { qt: "تحلیل بنیادی بدون گزارش حساب رسی توهمی بیش نیست", by: "ویدیوی «اهمیت حسابرسی در سرمایه گذاری»، یوتیوب، بهمن ۱۴۰۳، دقیقه ۶ (متن پیاده‌شده)", tb: tb(["ستون", "شیفته، خرداد ۱۴۰۵"], [["ارزش بازار برآوردی", "۱٬۴۸۰"], ["فروش ۲ ماهه", "۳۸۷"], ["فروش برآوردی سال", "۲٬۳۲۲"], ["حاشیه سود FIS", "۱۳.۳٪"], ["سود خالص برآوردی", "۳۱۴"], ["P/E آینده‌نگر", "۴.۷۱"], ["P/S آینده‌نگر", "۰.۶۴"], ["P/D آینده‌نگر", "۱۲.۵۴"], ["P/A", "۰.۹۳"], ["P/B", "۲.۸۹"], ["دوره گردش کالا", "۱۹۷ روز"], ["دوره وصول مطالبات", "۲۵ روز"], ["تقسیم سود ۱۴۰۲ و ۱۴۰۳", "۳۴٪ و ۴۱٪"]]) }),
      card("P/D آینده‌نگر در عمل", ["سود نقدی سال آینده هنوز اعلام نشده؛ پس آن را برآورد می‌کند: سود خالص برآوردی × میانگین نسبت تقسیم سال‌های اخیر.", "نمونه شرانل (تیر ۱۴۰۵): P/D با سود نقدی آخرین مجمع ۷.۸ بود؛ با سود برآوردی ۷٬۴۳۰ میلیارد تومان و میانگین تقسیم ۹۰٪، P/D آینده‌نگر حدود ۶.۵ شد.", "عددهای شیفته هم با همین روش جور درمی‌آیند: میانگین تقسیم دو سال (۳۴٪ و ۴۱٪) ۳۷.۵٪ است و ۱٬۴۸۰ ÷ (۳۱۴ × ۰.۳۷۵) ≈ ۱۲.۶؛ پست ۱۲.۵۴ نوشته (اختلاف از گرد کردن).", "سقف خرید را در یک ویدیو این‌طور می‌گوید: سود برآوردی × میانگین تقسیم دو سال × ۴.۵ تا ۵ = سقف ارزش بازار برای خرید؛ یعنی P/D زیر ۴.۵ تا ۵."], { f: "سود نقدی برآوردی = سود خالص برآوردی × میانگین نسبت تقسیم", qt: "با توجه به برآورد سود خالص 7430 میلیارد تومان تا پایان سال مالی و میانگین تقسیم سود 90 درصدی،نسبت ارزش بازار به سود نقدی برآوردی شرکت در محدوده 6.5 واحد قرار دارد", by: "کانال تلگرام پیشرفت مالی، پست ۲۲۲۶۹، تیر ۱۴۰۵" }),
      card("هلدینگ‌ها: P/80%NAV", ["برای هلدینگ‌ها قالب دیگری دارد. نمونه: صبا، شهریور ۱۴۰۵ (میلیارد تومان).", "به گفته او NAV روز را خودتان از گزارش پرتفوی کدال بسازید، با شرکت‌های غیربورسی؛ و زیان انباشته را از ارزش دارایی کم کنید.", "NAV از عددهای خود پست درمی‌آید: حقوق صاحبان سهام + ارزش روز سبد − بهای تمام‌شده سبد = ۲۷٬۰۷۱ + ۱۹۲٬۹۲۶ − ۱۹٬۲۴۵ = ۲۰۰٬۷۵۲.", "بعد ارزش بازار را با ۸۰٪ NAV می‌سنجد: ۹۴٬۱۸۵ ÷ ۱۶۰٬۶۰۱ ≈ ۵۹٪. زیر ۱۰۰٪ یعنی بازار هلدینگ را کمتر از ۸۰٪ ارزش دارایی‌هایش قیمت گذاشته است. دلیل عدد ۸۰٪ در پست‌ها نیامده.", "کنارش محک‌های هلدینگ را می‌آورد: تقسیم سود ۹۶٪ و ۹۵٪، نسبت مطالبات به دارایی ۲۵٪، و مبلغ سبد غیربورسی.", "همین معیار در پست‌های دیگرش: ونیکی ۵۴٪، ومعادن ۶۴٪، شستا ۱۰۸٪، تاپیکو ۱۵۰٪."], { f: "P/80%NAV = ارزش بازار ÷ (۰.۸ × NAV)" }),
      card("مقایسه درون یک صنعت", ["نوع دیگری از پست‌هایش: شرکت‌های یک صنعت را روی همین متغیرها کنار هم می‌گذارد. نمونه: صنعت پالایش، دی ۱۴۰۴.", "کمترین P/E و P/S آینده‌نگر: شاوان. بیشترین رشد فروش تجمعی: شپنا (۵۰٪). بیشترین حاشیه سود: شبندر (۱۰٪). کمترین نسبت مطالبات: شراز.", "هیچ شرکتی در همه ستون‌ها اول نیست؛ برای همین امتیاز FIS متغیرها را وزن می‌دهد و جمع می‌زند.", "حاشیه را هم فقط درون صنعت مقایسه می‌کند (درس «خلق ثروت، حاشیه صنعت و اندازه شرکت»)."], { qt: "کمترین P/E Forward صنعت مختص به #شاوان و کمترین P/S Forward مختص به #شاوان است.", by: "کانال تلگرام پیشرفت مالی، پست ۲۱۵۳۸، دی ۱۴۰۴" })
